(() => {
const core=window.ExpenseLedger,key='metro-daily-expenses-v1',root=document.querySelector('#expenses');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=c=>(c/100).toLocaleString('zh-TW',{minimumFractionDigits:c%100?2:0,maximumFractionDigits:2});let records=[],raw=null,available=true,editing=null,removed=null;
root.innerHTML=`<div class="section-head"><div><div class="eyebrow">LITTLE BITES, LITTLE NOTES</div><h2>今天，花了多少？</h2></div><span class="plan-label">新臺幣 TWD</span></div><div class="expense-date-row"><label for="expense-date">記帳日期</label><input id="expense-date" type="date" value="${core.today()}" required><button id="expense-today" type="button">回到今天</button></div><p id="expense-error" role="alert" hidden></p><div class="expense-layout"><div class="expense-total"><span id="expense-total-label">當日花費總額</span><strong id="expense-total" aria-live="polite">NT$ 0</strong><small id="expense-count">尚無紀錄</small><div id="expense-breakdown"></div><p>預算不限，好好記下每一筆。<br>實際支出由你輸入，不會自動帶入預估餐費。</p></div><form id="expense-form" class="expense-form"><h3 id="expense-form-title">新增一筆花費</h3><div class="expense-form-row"><label>類別<select id="expense-category">${core.categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label>金額（NT$）<input id="expense-amount" type="text" inputmode="decimal" placeholder="例如 250" maxlength="10" required autocomplete="off" aria-describedby="amount-hint"></label></div><small id="amount-hint">輸入大於 0 的金額，最多兩位小數。</small><label>店家或備註（選填）<input id="expense-title" maxlength="80" placeholder="例如：午餐小籠包、捷運車資" autocomplete="off"></label><div class="expense-form-actions"><button id="expense-submit" type="submit">＋ 記下這筆花費</button><button id="expense-cancel" type="button" hidden>取消修改</button></div></form></div><div class="expense-list-heading"><h3>當日明細</h3><span>修改與刪除後，總額會自動更新</span></div><div id="expense-undo" hidden><span>已刪除一筆紀錄。</span><button type="button" id="expense-restore">復原刪除</button></div><div id="expense-list"></div><p class="expense-storage">紀錄依日期儲存在此瀏覽器，不會跨手機同步；清除網站資料會移除記帳紀錄。日期以台北時間為準。</p>`;
const $=s=>root.querySelector(s),date=$('#expense-date'),form=$('#expense-form'),amount=$('#expense-amount');
function error(message){$('#expense-error').textContent=message;$('#expense-error').hidden=!message;}
function load(){try{raw=localStorage.getItem(key);records=core.decode(raw);available=true;error('')}catch{available=false;error('無法讀取花費紀錄，請確認瀏覽器允許儲存網站資料。既有資料未被覆寫。')}$('#expense-submit').disabled=!available;}
function store(next){if(!available)return false;try{if(localStorage.getItem(key)!==raw){load();render();error('另一個分頁已更新紀錄，明細已重新載入，請確認後再送出。');return false;}const nextRaw=JSON.stringify(next);localStorage.setItem(key,nextRaw);raw=nextRaw;records=next;error('');return true;}catch{error('儲存失敗，這筆變更尚未保存。請確認裝置儲存空間與瀏覽器設定後重試。');return false;}}
function cancel(){editing=null;form.reset();$('#expense-cancel').hidden=true;$('#expense-submit').textContent='＋ 記下這筆花費';$('#expense-form-title').textContent='新增一筆花費';amount.setCustomValidity('');}
function render(){const valid=core.validDate(date.value);const selected=core.summary(records,valid?date.value:'');$('#expense-total-label').textContent=valid?`${date.value.replaceAll('-','/')} · 花費總額`:'請選擇記帳日期';$('#expense-total').textContent='NT$ '+money(selected.total);$('#expense-count').textContent=selected.rows.length?`共 ${selected.rows.length} 筆支出`:'尚無紀錄';$('#expense-breakdown').innerHTML=core.categories.map(c=>`<div><span>${c}</span><b>NT$ ${money(selected.categories[c])}</b></div>`).join('');$('#expense-list').innerHTML=selected.rows.length?[...selected.rows].reverse().map(r=>`<article class="expense-item"><div><span class="expense-category-tag">${r.category}</span><strong>${escape(r.title||r.category+'支出')}</strong></div><b>NT$ ${money(r.cents)}</b><div class="expense-item-actions"><button type="button" data-edit-expense="${escape(r.id)}" aria-label="修改${escape(r.title||r.category)}">修改</button><button type="button" data-delete-expense="${escape(r.id)}" aria-label="刪除${escape(r.title||r.category)}">刪除</button></div></article>`).join(''):'<div class="expense-empty">這一天還沒有花費紀錄。<br>吃完一餐，記下第一筆吧。</div>';$('#expense-undo').hidden=!removed;$('#expense-submit').disabled=!available||!valid;}
form.addEventListener('submit',e=>{e.preventDefault();if(!core.validDate(date.value)){error('請選擇有效的記帳日期。');return;}const cents=core.parseAmount(amount.value);if(cents===null){amount.setCustomValidity('請輸入大於 0、最多兩位小數的金額（上限 9,999,999.99 元）。');amount.reportValidity();return;}const row={id:editing||crypto.randomUUID(),date:date.value,category:$('#expense-category').value,title:$('#expense-title').value.trim(),cents};if(!core.validRecord(row)){error('請確認金額、類別與備註內容。');return;}if(editing&&!records.some(r=>r.id===editing)){error('這筆紀錄已不存在，請取消修改後重新新增。');return;}const next=editing?records.map(r=>r.id===editing?row:r):[...records,row];const wasEditing=!!editing;if(store(next)){cancel();render();toast(wasEditing?'已更新花費與當日總額':'已記下花費並更新當日總額');}});
amount.oninput=()=>amount.setCustomValidity('');$('#expense-cancel').onclick=cancel;
date.onchange=()=>{cancel();render()};$('#expense-today').onclick=()=>{date.value=core.today();cancel();render()};
root.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-expense]'),del=e.target.closest('[data-delete-expense]');if(edit){const row=records.find(r=>r.id===edit.dataset.editExpense);if(!row)return;editing=row.id;$('#expense-category').value=row.category;$('#expense-title').value=row.title;amount.value=(row.cents/100).toFixed(2);amount.setCustomValidity('');$('#expense-form-title').textContent='修改這筆花費';$('#expense-submit').textContent='儲存修改';$('#expense-cancel').hidden=false;form.scrollIntoView({behavior:'smooth',block:'center'});amount.focus({preventScroll:true});}if(del){const row=records.find(r=>r.id===del.dataset.deleteExpense);if(!row)return;if(store(records.filter(r=>r.id!==row.id))){removed=row;if(editing===row.id)cancel();render();toast('已刪除，可按「復原刪除」還原');}}});
$('#expense-restore').onclick=()=>{if(!removed)return;const row=removed;if(records.some(r=>r.id===row.id)){removed=null;render();return;}if(store([...records,row])){removed=null;date.value=row.date;cancel();render();toast('已復原花費紀錄');}};
window.addEventListener('storage',e=>{if(e.key===key||e.key===null){load();render();}});load();render();
})();
